package com.bank.risk;

import java.util.logging.Logger;

public class MatrixChainPlanner {

    private static final Logger log = Logger.getLogger(MatrixChainPlanner.class.getName());

    public int minMultiplications(int[] p) {
        int n = p.length - 1;                          // number of matrices
        int[][] dp = new int[n + 1][n + 1];            // 1-indexed matrices
        for (int len = 2; len <= n; len++) {           // chain length
            for (int i = 1; i + len - 1 <= n; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {           // split between k and k+1
                    int cost = dp[i][k] + dp[k + 1][j] + p[i - 1] * p[k] * p[j];
                    dp[i][j] = Math.min(dp[i][j], cost);
                }
            }
        }
        int result = dp[1][n];
        log.info(() -> "Minimum scalar multiplications = " + result);
        return result;
    }
}
