package com.bank.risk;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MatrixChainDemo {

    private static final Logger log = Logger.getLogger(MatrixChainDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Matrix Chain Planner (MCM)");
        MatrixChainPlanner planner = new MatrixChainPlanner();
        // matrices: 40x20, 20x30, 30x10, 10x30
        log.info("{40,20,30,10,30} → " + planner.minMultiplications(new int[]{40,20,30,10,30})); // 26000
        log.info("{10,20,30} → " + planner.minMultiplications(new int[]{10,20,30}));              // 6000
    }
}
